// Simple Meteor Dodge game
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 400;
  const height = canvas.height = canvas.clientHeight || 600;

  // Ship
  const ship = { w: 40, h: 20, x: width / 2, y: height - 30, speed: 5 };

  // Meteors array
  const meteors = [];
  const meteorSpawnInterval = 800; // ms
  let lastSpawn = 0;
  let score = 0;
  let lives = 3;
  let gameOver = false;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => keys[e.key] = true);
  window.addEventListener('keyup', e => keys[e.key] = false);
  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    ship.x = e.clientX - rect.left;
  });

  function spawnMeteor() {
    const size = Math.random() * 30 + 20;
    meteors.push({ x: Math.random() * (width - size), y: -size, w: size, h: size, speed: Math.random() * 2 + 2 });
  }

  function update(dt) {
    if (gameOver) return;
    // Ship movement (arrow keys)
    if (keys.ArrowLeft) ship.x -= ship.speed;
    if (keys.ArrowRight) ship.x += ship.speed;
    // Clamp ship position
    ship.x = Math.max(0, Math.min(width - ship.w, ship.x));

    // Spawn meteors
    if (performance.now() - lastSpawn > meteorSpawnInterval) {
      spawnMeteor();
      lastSpawn = performance.now();
    }

    // Update meteors
    for (let i = meteors.length - 1; i >= 0; i--) {
      const m = meteors[i];
      m.y += m.speed;
      // Collision with ship
      if (m.x < ship.x + ship.w && m.x + m.w > ship.x && m.y < ship.y + ship.h && m.y + m.h > ship.y) {
        lives--;
        meteors.splice(i, 1);
        if (lives <= 0) gameOver = true;
        continue;
      }
      // Remove off-screen meteors, increment score
      if (m.y > height) {
        meteors.splice(i, 1);
        score++;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Draw ship
    ctx.fillStyle = '#0af';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // Draw meteors
    ctx.fillStyle = '#a44';
    meteors.forEach(m => ctx.fillRect(m.x, m.y, m.w, m.h));
    // UI
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Lives: ${lives}`, 10, 40);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '32px sans-serif';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  let lastTime = 0;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
